import{_ as t,a as r,o as a,a6 as i}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"URL Rewrites","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/marketing/search-seo/url-rewrites/index.md","filePath":"api/graphql-api/admin/marketing/search-seo/url-rewrites/index.md","lastUpdated":1787725411000}'),o={name:"api/graphql-api/admin/marketing/search-seo/url-rewrites/index.md"};function d(s,e,n,l,h,c){return a(),r("div",null,e[0]||(e[0]=[i('<h1 id="url-rewrites" tabindex="-1">URL Rewrites <a class="header-anchor" href="#url-rewrites" aria-label="Permalink to &quot;URL Rewrites&quot;">​</a></h1><p>A <strong>URL rewrite</strong> redirects an old or custom path to a target path, so links keep working when a product, category, or CMS page slug changes. It mirrors the admin <strong>Marketing → Search &amp; SEO → URL Rewrites</strong> screen.</p><h2 id="how-a-url-rewrite-works" tabindex="-1">How a URL rewrite works <a class="header-anchor" href="#how-a-url-rewrite-works" aria-label="Permalink to &quot;How a URL rewrite works&quot;">​</a></h2><p>Each rewrite maps a <strong>source path</strong> to a <strong>destination path</strong> for a given entity and locale.</p><ul><li><strong><code>entityType</code></strong> ties the rewrite to a <code>product</code>, <code>category</code>, or <code>cms_page</code> — the kind of storefront page the rewrite is for.</li><li><strong><code>requestPath</code></strong> is the path the shopper requests (the old or custom slug).</li><li><strong><code>targetPath</code></strong> is where that request is sent.</li><li><strong><code>redirectType</code></strong> decides the kind of redirect:</li></ul><table tabindex="0"><thead><tr><th><code>redirectType</code></th><th>Meaning</th><th>Use when</th></tr></thead><tbody><tr><td><code>301</code></td><td>Permanent redirect</td><td>The old path is gone for good; search engines should pass ranking to the new path</td></tr><tr><td><code>302</code></td><td>Temporary redirect</td><td>The move is temporary; keep the old path&#39;s ranking</td></tr></tbody></table><ul><li><strong><code>locale</code></strong> scopes the rewrite to a single storefront locale.</li></ul><p><strong>Keeping old links alive.</strong> When a slug changes, the rewrite makes the old link still resolve to the right page. This complements the automatic rewrites the store creates when a slug is edited — you can also add your own custom redirects here.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/url-rewrites-list.html">List</a></td><td><code>adminMarketingUrlRewrites</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/url-rewrites-detail.html">Detail</a></td><td><code>adminMarketingUrlRewrite</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/url-rewrites-create.html">Create</a></td><td><code>createAdminMarketingUrlRewrite</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/url-rewrites-update.html">Update</a></td><td><code>updateAdminMarketingUrlRewrite</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/url-rewrites-delete.html">Delete</a></td><td><code>deleteAdminMarketingUrlRewrite</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/url-rewrites-mass-delete.html">Mass Delete</a></td><td><code>createAdminMarketingUrlRewriteMassDelete</code> mutation</td></tr></tbody></table>',10)]))}const m=t(o,[["render",d]]);export{g as __pageData,m as default};
